/*
 * A333401  a(n) is the distance between n and -n in A333400.
 * https://oeis.org/A333401
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = |pos(n) - pos(-n)|, where pos(m) is the index of m in
 *            A333400. A333400 is generated by greedy search (hash sets for
 *            used terms and partial sums)
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 103 terms through n = 9737 (2026-11-08)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    long long *k;
    long long *v;
    unsigned char *u;
    size_t cap, cnt;
} A333401_tab;

static size_t A333401_hash(long long key, size_t cap)
{
    uint64_t x = (uint64_t)key * 0x9E3779B97F4A7C15ULL;
    x ^= x >> 29;
    return (size_t)(x & (uint64_t)(cap - 1));
}

static void A333401_init(A333401_tab *t, size_t cap)
{
    t->cap = cap;
    t->cnt = 0;
    t->k = (long long *)malloc(cap * sizeof(long long));
    t->v = (long long *)malloc(cap * sizeof(long long));
    t->u = (unsigned char *)calloc(cap, 1);
}

static long long A333401_find(const A333401_tab *t, long long key)
{
    size_t i = A333401_hash(key, t->cap);
    while (t->u[i]) {
        if (t->k[i] == key) return t->v[i];
        i = (i + 1) & (t->cap - 1);
    }
    return -1;
}

static void A333401_put(A333401_tab *t, long long key, long long val);

static void A333401_grow(A333401_tab *t)
{
    A333401_tab nt;
    A333401_init(&nt, t->cap * 2);
    for (size_t i = 0; i < t->cap; ++i)
        if (t->u[i]) A333401_put(&nt, t->k[i], t->v[i]);
    free(t->k); free(t->v); free(t->u);
    *t = nt;
}

static void A333401_put(A333401_tab *t, long long key, long long val)
{
    if ((t->cnt + 1) * 2 > t->cap) A333401_grow(t);
    size_t i = A333401_hash(key, t->cap);
    while (t->u[i]) {
        if (t->k[i] == key) { t->v[i] = val; return; }
        i = (i + 1) & (t->cap - 1);
    }
    t->u[i] = 1;
    t->k[i] = key;
    t->v[i] = val;
    t->cnt++;
}

static long long A333401_cand(long long idx)
{
    if (idx == 0) return 0;
    long long mag = (idx + 1) >> 1;
    return (idx & 1) ? -mag : mag;
}

seq_t a(idx_t n)
{
    static int inited = 0;
    static A333401_tab terms, sums;
    static long long len = 0, cur_sum = 0, ptr = 0;

    if (!inited) {
        A333401_init(&terms, 1024);
        A333401_init(&sums, 1024);
        inited = 1;
    }

    long long m = (long long)n;
    for (;;) {
        long long p = A333401_find(&terms, m);
        long long q = A333401_find(&terms, -m);
        if (p >= 0 && q >= 0) {
            long long d = p > q ? p - q : q - p;
            return (seq_t)d;
        }
        /* generate next term */
        while (A333401_find(&terms, A333401_cand(ptr)) >= 0) ++ptr;
        for (long long idx = ptr; ; ++idx) {
            long long c = A333401_cand(idx);
            if (A333401_find(&terms, c) >= 0) continue;
            long long ns = cur_sum + c;
            if (A333401_find(&sums, ns) >= 0) continue;
            ++len;
            A333401_put(&terms, c, len);
            A333401_put(&sums, ns, len);
            cur_sum = ns;
            break;
        }
    }
}
